using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    /// <summary>Fetches data from an external API endpoint.</summary>
    [McpServerTool, Description("Fetch JSON data from the external API for a given resource path.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        [Description("The API resource path to fetch (e.g. \"users/1\").")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        using var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Summarize the provided text into key points.")]
    public static ChatMessage Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Target number of bullet points (default: 5).")] int maxPoints = 5)
    {
        return new ChatMessage(
            ChatRole.User,
            $"""
            Summarize the following text into at most {maxPoints} concise bullet points.
            Focus on the most important facts and conclusions.

            Text:
            {text}
            """);
    }
}

